(121, 8, 107, '专业教材套装', 'TEXTBOOK001', 0, 1, 1, 1, 1, 121, 25, 242.00, 199.00, 12, 12, '大学专业教材', '计算机专业教材套装', 329.00, 60, 6, '套', 2.80, 0, '1,2,3', '教材', '专业书籍', 0, '文具品牌', '图书文具');

-- 5. 验证查询 - 测试用户兴趣标签
SELECT '用户兴趣标签测试' as test_type,
       pc.name as tag,
       COUNT(DISTINCT oo.member_id) as count
FROM oms_order oo
JOIN oms_order_item ooi ON oo.id = ooi.order_id
JOIN pms_product pp ON ooi.product_id = pp.id
JOIN pms_product_category pc ON pp.product_category_id = pc.id
WHERE oo.status != 4
    AND oo.create_time BETWEEN '2024-07-01' AND '2024-07-31'
GROUP BY pc.name
ORDER BY count DESC
LIMIT 20;

-- 6. 验证查询 - 测试用户消费偏好
SELECT '用户消费偏好测试' as test_type,
       pc.name as category,
       COALESCE(SUM(ooi.real_amount), 0) as amount
FROM oms_order oo
JOIN oms_order_item ooi ON oo.id = ooi.order_id
JOIN pms_product pp ON ooi.product_id = pp.id
JOIN pms_product_category pc ON pp.product_category_id = pc.id
WHERE oo.status != 4
    AND oo.create_time BETWEEN '2024-07-01' AND '2024-07-31'
GROUP BY pc.name
ORDER BY amount DESC
LIMIT 10;

-- 7. 用户购买行为统计
SELECT '用户购买行为分析' as analysis_type,
       m.nickname as user_name,
       COUNT(DISTINCT oo.id) as order_count,
       COUNT(DISTINCT pc.name) as category_count,
       SUM(ooi.real_amount) as total_amount,
       GROUP_CONCAT(DISTINCT pc.name ORDER BY pc.name) as interested_categories
FROM oms_order oo
JOIN ums_member m ON oo.member_id = m.id
JOIN oms_order_item ooi ON oo.id = ooi.order_id
JOIN pms_product pp ON ooi.product_id = pp.id
JOIN pms_product_category pc ON pp.product_category_id = pc.id
WHERE oo.status != 4
    AND oo.create_time BETWEEN '2024-07-01' AND '2024-07-31'
GROUP BY m.id, m.nickname
ORDER BY total_amount DESC;
